import React, { useEffect, useState, useRef } from 'react'
import { FormItem, FormContainer } from 'components/ui'
import AdaptableCard from 'components/shared/AdaptableCard'
import Input from 'components/ui/Input'
import Select from 'components/ui/Select'
import DatePicker from 'components/ui/DatePicker'
import Button from 'components/ui/Buttons'
import StickyFooter from 'components/shared/StickyFooter'
import { Field, Form, FieldArray, Formik, getIn } from 'formik'
import { useNavigate, useParams } from 'react-router-dom'
import * as Yup from 'yup'
import Table from 'components/ui/Table'
import { HiMinus } from 'react-icons/hi'
import '../PurchaseOrder/AddEditPurchaseOrder.css'
import NumberFormat from 'react-number-format'
import Upload from 'components/ui/Upload'
import toast from 'components/ui/toast'
import Checkbox from 'components/ui/Checkbox'
import Notification from 'components/ui/Notification'
import {
    apiFinanceVoucherDelete,
    apiFinanceVoucherGetSingle,
    apiFinanceVoucherPost,
    apiFinanceVoucherUpdate,
} from 'services/FinanceVoucherService'
import { apiPurchaseOrderMasterData } from 'services/PurchaseOrderService'
import { saveAs } from 'file-saver'

const { Tr, Th, Td, THead, TBody } = Table

const validationSchema = Yup.object().shape({
    invoice_date: Yup.string().required('Invoice Date Is Required').nullable(),
    vendor_id: Yup.string().required('Vendor Is Required'),
    depot_id: Yup.string().required('Depot Is Required'),
    invoice_no: Yup.string().required('Invoice No Is Required'),
    po_no: Yup.string().required('PO No Is Required').nullable(),
    date_of_processing: Yup.string().required('Payment Due Date Is Required'),
    paymentVoucherItems: Yup.array().of(
        Yup.object()
            .shape({
                particulars: Yup.string().required(' '),
                qty: Yup.string().required(' '),
                rate: Yup.string().required(' '),
                tax_per: Yup.string().required(' '),
            })
            .required('Details is Required')
    ),
})

const fieldFeedback = (form, name) => {
    const error = getIn(form.errors, name)
    const touch = getIn(form.touched, name)
    return {
        errorMessage: error || '',
        invalid: typeof touch === 'undefined' ? false : error && touch,
    }
}

const MAX_UPLOAD = 10

const beforeUpload = (file, fileList) => {
    let valid = true

    const allowedFileType = ['image/jpeg', 'image/png', 'application/pdf']
    const MAX_FILE_SIZE = 2000000

    if (fileList.length >= MAX_UPLOAD) {
        return `You can only upload ${MAX_UPLOAD} file(s)`
    }

    if (file) {
        for (const f of file) {
            if (!allowedFileType.includes(f.type)) {
                valid = 'Please upload a .jpeg or .png file!'
            }

            if (f.size >= MAX_FILE_SIZE) {
                valid = 'Upload image cannot more then 500kb!'
            }
        }
    }

    return valid
}

const AddFinanceVoucher = () => {
    const [financeVoucherData, setFinanceVoucherData] = useState({
        invoice_date: '', //YYYY-MM-DD
        vendor_id: '',
        depot_id: '',
        invoice_no: '',
        po_no: '',
        doc_document: [],
        document_name: '',
        date_of_processing: '',
        pay_immediately: '',
        paymentVoucherItems: [
            {
                particulars: '',
                qty: '',
                rate: '',
                tax_per: '',
                amount: '',
                tax_amt: '',
                total_amt: '',
            },
        ],
        total_payable: '',
        round_off_amount: '',
        tds_per: '',
        tdsamount: '',
        final_amount: '',
        remarks: '',
    })
    const [actionBtn, setActionBtn] = useState({
        approve: false,
        delete: false,
        update: false,
    })
    const [masterOption, setMasterOption] = useState({
        vendors: [],
        depots: [],
    })
    const [loading, setLoading] = useState(false)
    const navigate = useNavigate()
    const financeVoucherId = useParams()
    const formRef = useRef()

    const deleteFinanceVoucher = async () => {
        await apiFinanceVoucherDelete(financeVoucherId.financeid)
            .then((data) => {
                console.log(data)
                if (data.status === 200) {
                    formRef.current.setSubmitting(false)
                    toast.push(
                        <Notification title="Success" type="success" closable>
                            {data.data['message']}
                        </Notification>
                    )
                    formRef.current.resetForm()
                    navigate('/transaction/finance-voucher')
                }
            })
            .catch((error) => {
                let errorData = error.response['data']['error']['errors']
                if (error.response.status === 422) {
                    for (const errMsg in errorData) {
                        formRef.current.setFieldError(
                            errMsg,
                            errorData[errMsg]['message']
                        )
                        toast.push(
                            <Notification title="Error" type="danger" closable>
                                {errorData[errMsg]['message']}
                            </Notification>
                        )
                    }
                } else if (error.response.status === 500) {
                    console.log(errorData)
                    toast.push(
                        <Notification title="Error" type="danger" closable>
                            {error.response.data['message']}
                        </Notification>
                    )
                }
            })
    }

    const handleTotal = (data) => {
        let total = 0
        data.values.paymentVoucherItems.map((value) => {
            if (value.total_amt > 0) {
                total += value.total_amt
            }
            return total
        })
        data.setFieldValue('total_payable', total)
        data.setFieldValue('round_off_amount', Math.round(total) - total)
        data.setFieldValue('final_amount', Math.round(total))
    }

    const calcTDS = (e) => {
        formRef.current.setFieldValue('tds_per', parseFloat(e.target.value))
        const tds_per = parseFloat(e.target.value)
        const amount = formRef.current.values['total_payable']
        const tds_amount = (parseFloat(amount) * parseFloat(tds_per)) / 100
        formRef.current.setFieldValue('tdsamount', tds_amount)
        const roundOff =
            Math.round(
                (Math.round(formRef.current.values.total_payable - tds_amount) -
                    Math.round(
                        (formRef.current.values.total_payable - tds_amount) *
                            100
                    ) /
                        100) *
                    100
            ) / 100
        const net_amount =
            formRef.current.values.total_payable - tds_amount + roundOff
        formRef.current.setFieldValue('round_off_amount', roundOff)
        formRef.current.setFieldValue('final_amount', net_amount)
    }

    const calcRound = (e) => {
        const roundOff = parseFloat(e.target.value)
        formRef.current.setFieldValue('round_off_amount', roundOff)
        const tds_amount = parseFloat(formRef.current.values.tdsamount)
        const net_amount =
            formRef.current.values.total_payable - tds_amount + roundOff
        formRef.current.setFieldValue('final_amount', net_amount)
    }

    const download = async (url) => {
        saveAs(url)
    }

    useEffect(() => {
        const fetchData = async () => {
            if (financeVoucherId.financeid) {
                setLoading(true)
                await apiFinanceVoucherGetSingle(financeVoucherId.financeid)
                    .then((data) => {
                        if (data.status === 200) {
                            console.log(data.data['paymentVoucher'])
                            setActionBtn({
                                approve: data.data['action']['approve'],
                                update: data.data['action']['update'],
                                delete: data.data['action']['delete'],
                            })
                            setFinanceVoucherData({
                                invoice_date:
                                    data.data['paymentVoucher'].invoice_date !=
                                        '' ||
                                    data.data['paymentVoucher'].invoice_date !=
                                        null
                                        ? new Date(
                                              data.data[
                                                  'paymentVoucher'
                                              ].invoice_date
                                          )
                                        : '',
                                invoice_no:
                                    data.data['paymentVoucher'].invoice_no !=
                                        '' ||
                                    data.data['paymentVoucher'].invoice_no !=
                                        null
                                        ? data.data['paymentVoucher'].invoice_no
                                        : '',
                                po_no:
                                    data.data['paymentVoucher'].po_no != '' ||
                                    data.data['paymentVoucher'].po_no != null
                                        ? data.data['paymentVoucher'].po_no
                                        : '',
                                date_of_processing:
                                    data.data['paymentVoucher']
                                        .date_of_processing != '' ||
                                    data.data['paymentVoucher']
                                        .date_of_processing != null
                                        ? data.data['paymentVoucher']
                                              .date_of_processing
                                        : '',
                                pay_immediately:
                                    data.data['paymentVoucher']
                                        .pay_immediately == 1
                                        ? true
                                        : false,
                                vendor_id:
                                    data.data['paymentVoucher'].vendor_id !=
                                        '' ||
                                    data.data['paymentVoucher'].vendor_id !=
                                        null
                                        ? data.data['paymentVoucher'].vendor_id
                                        : '',
                                depot_id:
                                    data.data['paymentVoucher'].depot_id !=
                                        '' ||
                                    data.data['paymentVoucher'].depot_id != null
                                        ? data.data['paymentVoucher'].depot_id
                                        : '',
                                document_name:
                                    data.data['paymentVoucher'].document_name !=
                                        '' ||
                                    data.data['paymentVoucher'].document_name !=
                                        null
                                        ? data.data[
                                              'paymentVoucher'
                                          ].document_name.split('|')
                                        : [],
                                round_off_amount:
                                    data.data['paymentVoucher']
                                        .round_off_amount != '' ||
                                    data.data['paymentVoucher']
                                        .round_off_amount != null
                                        ? data.data['paymentVoucher']
                                              .round_off_amount
                                        : '',
                                paymentVoucherItems:
                                    data.data['paymentVoucher']
                                        .paymentVoucherItems.length > 0
                                        ? data.data[
                                              'paymentVoucher'
                                          ].paymentVoucherItems.map(
                                              (value, index) => {
                                                  return {
                                                      particulars:
                                                          value.particulars,
                                                      qty: value.qty,
                                                      rate: value.rate,
                                                      tax_per: value.tax_per,
                                                      amount: value.amount,
                                                      tax_amt: value.tax_amt,
                                                      total_amt:
                                                          value.total_amt,
                                                  }
                                              }
                                          )
                                        : [],
                                total_payable:
                                    data.data['paymentVoucher'].total_payable !=
                                        '' ||
                                    data.data['paymentVoucher'].total_payable !=
                                        null
                                        ? data.data['paymentVoucher']
                                              .total_payable
                                        : 0,
                                round_off_amount:
                                    data.data['paymentVoucher']
                                        .round_off_amount != '' ||
                                    data.data['paymentVoucher']
                                        .round_off_amount != null
                                        ? data.data['paymentVoucher']
                                              .round_off_amount
                                        : 0,
                                tds_per:
                                    data.data['paymentVoucher'].tds_per != '' ||
                                    data.data['paymentVoucher'].tds_per != null
                                        ? data.data['paymentVoucher'].tds_per
                                        : 0,
                                tdsamount:
                                    data.data['paymentVoucher'].tdsamount !=
                                        '' ||
                                    data.data['paymentVoucher'].tdsamount !=
                                        null
                                        ? data.data['paymentVoucher'].tdsamount
                                        : 0,
                                final_amount:
                                    data.data['paymentVoucher'].final_amount !=
                                        '' ||
                                    data.data['paymentVoucher'].final_amount !=
                                        null
                                        ? data.data['paymentVoucher']
                                              .final_amount
                                        : 0,
                                remarks:
                                    data.data['paymentVoucher'].remarks != '' ||
                                    data.data['paymentVoucher'].remarks != null
                                        ? data.data['paymentVoucher'].remarks
                                        : '',
                            })
                            // console.log(data.data['masterData'])
                            setMasterOption({
                                vendors: data.data['masterData'].vendors.map(
                                    (value) => {
                                        return {
                                            value: value.id,
                                            label: value.vendor_name,
                                            state: value.state,
                                        }
                                    }
                                ),
                                depots: data.data['masterData'].depots.map(
                                    (value) => {
                                        return {
                                            value: value.id,
                                            label: value.depot_name,
                                            state: value.state,
                                        }
                                    }
                                ),
                            })
                            setLoading(false)
                        }
                    })
                    .catch((error) => {
                        console.log(error)
                        setLoading(false)
                    })
            } else {
                setLoading(true)
                await apiPurchaseOrderMasterData()
                    .then((data) => {
                        if (data.status === 200) {
                            setMasterOption({
                                vendors: data.data['masterData'].vendors.map(
                                    (value) => {
                                        return {
                                            value: value.id,
                                            label: value.vendor_name,
                                            state: value.state,
                                        }
                                    }
                                ),
                                depots: data.data['masterData'].depots.map(
                                    (value) => {
                                        return {
                                            value: value.id,
                                            label: value.depot_name,
                                            state: value.state,
                                        }
                                    }
                                ),
                            })
                            setLoading(false)
                        }
                    })
                    .catch((error) => {
                        console.logO(error)
                        setLoading(false)
                    })
            }
            return true
        }
        fetchData()
    }, [])
    return (
        <Formik
            enableReinitialize={true}
            initialValues={{
                invoice_date:
                    financeVoucherData.invoice_date === ''
                        ? new Date()
                        : new Date(financeVoucherData.invoice_date),
                vendor_id: financeVoucherData.vendor_id,
                depot_id: financeVoucherData.depot_id,
                invoice_no: financeVoucherData.invoice_no,
                po_no: financeVoucherData.po_no,
                doc_document: [],
                document_name: [],
                date_of_processing: new Date(
                    financeVoucherData.date_of_processing
                ),
                pay_immediately: financeVoucherData.pay_immediately,
                paymentVoucherItems:
                    financeVoucherData.paymentVoucherItems == []
                        ? []
                        : financeVoucherData.paymentVoucherItems,
                total_payable: financeVoucherData.total_payable,
                round_off_amount: financeVoucherData.round_off_amount,
                tds_per: financeVoucherData.tds_per,
                tdsamount: financeVoucherData.tdsamount,
                final_amount: financeVoucherData.final_amount,
                remarks: financeVoucherData.remarks,
            }}
            innerRef={formRef}
            validationSchema={validationSchema}
            onSubmit={async (values, actions) => {
                console.log(values)
                const formData = new FormData()
                for (const i in values) {
                    // console.log(i)
                    if (i === 'paymentVoucherItems') {
                        formData.append(i, JSON.stringify(values[i]))
                    } else if (i === 'doc_document') {
                        for (const val of values[i]) {
                            formData.append('doc_document', val)
                        }
                    } else {
                        formData.append(i, values[i])
                    }
                }
                // setSubmitting(false)
                if (financeVoucherId.financeid) {
                    // console.log(values)
                    await apiFinanceVoucherUpdate({
                        values: formData,
                        ...{ id: financeVoucherId.financeid },
                    })
                        .then((data) => {
                            console.log(data)
                            if (data.status === 200) {
                                actions.setSubmitting(false)
                                toast.push(
                                    <Notification
                                        title="Success"
                                        type="success"
                                        closable
                                    >
                                        {data.data['message']}
                                    </Notification>
                                )
                                actions.resetForm()
                                navigate('/transaction/finance-voucher')
                            }
                        })
                        .catch((error) => {
                            let errorData =
                                error.response['data']['error']['errors']
                            if (error.response.status === 422) {
                                for (const errMsg in errorData) {
                                    actions.setFieldError(
                                        errMsg,
                                        errorData[errMsg]['message']
                                    )
                                    toast.push(
                                        <Notification
                                            title="Error"
                                            type="danger"
                                            closable
                                        >
                                            {errorData[errMsg]['message']}
                                        </Notification>
                                    )
                                }
                            } else if (error.response.status === 500) {
                                console.log(errorData)
                                toast.push(
                                    <Notification
                                        title="Error"
                                        type="danger"
                                        closable
                                    >
                                        {error.response.data['message']}
                                    </Notification>
                                )
                            }
                        })
                } else {
                    console.log(values)
                    await apiFinanceVoucherPost(formData)
                        .then((data) => {
                            if (data.status === 201) {
                                console.log(data)
                                actions.setSubmitting(false)
                                actions.resetForm()
                                toast.push(
                                    <Notification
                                        title="Success"
                                        type="success"
                                        closable
                                    >
                                        {data.data['message']}
                                    </Notification>
                                )
                                navigate('/transaction/finance-voucher')
                            }
                        })
                        .catch((error) => {
                            let errorData =
                                error.response['data']['error']['errors']
                            actions.setSubmitting(false)
                            if (error.response.status === 422) {
                                errorData.map((err) => {
                                    // console.log(err);
                                    actions.setFieldError(err.path, err.message)
                                    toast.push(
                                        <Notification
                                            title="Error"
                                            type="danger"
                                            closable
                                        >
                                            {err.message}
                                        </Notification>
                                    )
                                    return true
                                })
                            } else if (error.response.status === 500) {
                                console.log(errorData)
                                toast.push(
                                    <Notification
                                        title="Error"
                                        type="danger"
                                        closable
                                    >
                                        {error.response.data['message']}
                                    </Notification>
                                )
                            }
                        })
                }
            }}
        >
            {({ values, touched, errors, resetForm, isSubmitting }) => {
                const paymentVoucherItems = values.paymentVoucherItems
                return (
                    <Form>
                        <AdaptableCard className="card-shadow mb-2">
                            <h5 className="mb-6">
                                {' '}
                                {financeVoucherId.financeid
                                    ? 'Edit'
                                    : 'Add'}{' '}
                                Finance Voucher
                            </h5>
                            <FormContainer layout="horizontal" size="sm">
                                <div className="grid grid-cols-1 md:grid-cols-3 gap-x-8 gap-y-2">
                                    <FormItem
                                        asterisk
                                        label="Vendor"
                                        invalid={
                                            errors.vendor_id &&
                                            touched.vendor_id
                                        }
                                        errorMessage={errors.vendor_id}
                                    >
                                        <Field name="vendor_id">
                                            {({ field, form }) => (
                                                <Select
                                                    field={field}
                                                    form={form}
                                                    options={
                                                        masterOption.vendors
                                                    }
                                                    // onFocus={onFocus}
                                                    isLoading={loading}
                                                    value={masterOption.vendors.filter(
                                                        (option) =>
                                                            option.value ===
                                                            values.vendor_id
                                                    )}
                                                    onChange={(option) => {
                                                        return form.setFieldValue(
                                                            field.name,
                                                            option?.value
                                                        )
                                                    }}
                                                    isDisabled={
                                                        actionBtn.approve
                                                    }
                                                />
                                            )}
                                        </Field>
                                    </FormItem>
                                    <FormItem
                                        asterisk
                                        label="Depot"
                                        invalid={
                                            errors.depot_id && touched.depot_id
                                        }
                                        errorMessage={errors.depot_id}
                                    >
                                        <Field name="depot_id">
                                            {({ field, form }) => (
                                                <Select
                                                    field={field}
                                                    form={form}
                                                    options={
                                                        masterOption.depots
                                                    }
                                                    // onFocus={onFocus}
                                                    isLoading={loading}
                                                    value={masterOption.depots.filter(
                                                        (option) =>
                                                            option.value ===
                                                            values.depot_id
                                                    )}
                                                    onChange={(option) => {
                                                        return form.setFieldValue(
                                                            field.name,
                                                            option?.value
                                                        )
                                                    }}
                                                    isDisabled={
                                                        actionBtn.approve
                                                    }
                                                />
                                            )}
                                        </Field>
                                    </FormItem>
                                    <FormItem
                                        asterisk
                                        label="Invoice Date"
                                        invalid={
                                            errors.invoice_date &&
                                            touched.invoice_date
                                        }
                                        errorMessage={errors.invoice_date}
                                    >
                                        <Field
                                            autoComplete="off"
                                            name="invoice_date"
                                        >
                                            {({ field, form }) => (
                                                <DatePicker
                                                    inputFormat="DD-MM-YYYY"
                                                    // inputtable
                                                    // inputtableBlurClose={false}
                                                    field={field}
                                                    placeholder="Invoice Date"
                                                    form={form}
                                                    value={values.invoice_date}
                                                    onChange={(option) => {
                                                        let date = new Date(
                                                            option
                                                        )
                                                        return form.setFieldValue(
                                                            field.name,
                                                            `${date.getFullYear()}-${
                                                                date.getMonth() <
                                                                10
                                                                    ? '0' +
                                                                      (date.getMonth() +
                                                                          1)
                                                                    : date.getMonth() +
                                                                      1
                                                            }-${
                                                                date.getDate() <
                                                                10
                                                                    ? '0' +
                                                                      date.getDate()
                                                                    : date.getDate()
                                                            }`
                                                        )
                                                    }}
                                                    disabled={actionBtn.approve}
                                                />
                                            )}
                                        </Field>
                                    </FormItem>
                                    <div>
                                        <FormItem
                                            label="Invoice No."
                                            invalid={
                                                errors.invoice_no &&
                                                touched.invoice_no
                                            }
                                            errorMessage={errors.invoice_no}
                                        >
                                            <Field
                                                type="text"
                                                name="invoice_no"
                                                placeholder="Invoice No."
                                                component={Input}
                                                disabled={actionBtn.approve}
                                            />
                                        </FormItem>
                                    </div>
                                    <div>
                                        <FormItem
                                            label="PO No."
                                            invalid={
                                                errors.po_no && touched.po_no
                                            }
                                            errorMessage={errors.po_no}
                                        >
                                            <Field
                                                type="text"
                                                name="po_no"
                                                placeholder="PO No."
                                                component={Input}
                                                disabled={actionBtn.approve}
                                            />
                                        </FormItem>
                                    </div>
                                    <div>
                                        <FormItem
                                            label="Files"
                                            invalid={Boolean(
                                                errors.doc_document &&
                                                    touched.doc_document
                                            )}
                                            errorMessage={errors.doc_document}
                                        >
                                            <Field name="doc_document">
                                                {({ field, form }) => (
                                                    <div>
                                                        <div>
                                                            <Upload
                                                                beforeUpload={
                                                                    beforeUpload
                                                                }
                                                                fileList={
                                                                    values.doc_document
                                                                }
                                                                onChange={(
                                                                    files
                                                                ) =>
                                                                    form.setFieldValue(
                                                                        field.name,
                                                                        files
                                                                    )
                                                                }
                                                                onFileRemove={(
                                                                    files
                                                                ) =>
                                                                    form.setFieldValue(
                                                                        field.name,
                                                                        files
                                                                    )
                                                                }
                                                                disabled={
                                                                    actionBtn.approve
                                                                }
                                                                multiple
                                                            />
                                                        </div>
                                                        <div
                                                            className={
                                                                (financeVoucherData
                                                                    .document_name
                                                                    .length > 0
                                                                    ? 'visible'
                                                                    : 'hidden') +
                                                                ' absolute left-[80px] top-0'
                                                            }
                                                        >
                                                            {financeVoucherData
                                                                .document_name
                                                                .length > 0 &&
                                                                financeVoucherData.document_name.map(
                                                                    (value) => (
                                                                        <p
                                                                            className="mb-1 cursor-pointer"
                                                                            onClick={() =>
                                                                                download(
                                                                                    value
                                                                                )
                                                                            }
                                                                        >
                                                                            {
                                                                                value
                                                                            }{' '}
                                                                        </p>
                                                                    )
                                                                )}
                                                        </div>
                                                    </div>
                                                )}
                                            </Field>
                                        </FormItem>
                                    </div>
                                    <FormItem
                                        asterisk
                                        label="Payment Due Date"
                                        invalid={
                                            errors.date_of_processing &&
                                            touched.date_of_processing
                                        }
                                        errorMessage={errors.date_of_processing}
                                    >
                                        <Field
                                            autoComplete="off"
                                            name="date_of_processing"
                                        >
                                            {({ field, form }) => (
                                                <DatePicker
                                                    inputFormat="DD-MM-YYYY"
                                                    // inputtable
                                                    // inputtableBlurClose={false}
                                                    field={field}
                                                    placeholder="Payment Due Date"
                                                    form={form}
                                                    value={
                                                        values.date_of_processing
                                                    }
                                                    onChange={(option) => {
                                                        return form.setFieldValue(
                                                            field.name,
                                                            option
                                                        )
                                                    }}
                                                    disabled={actionBtn.approve}
                                                />
                                            )}
                                        </Field>
                                    </FormItem>
                                    <FormItem
                                        asterisk
                                        label="Pay Immediately"
                                        invalid={
                                            errors.pay_immediately &&
                                            touched.pay_immediately
                                        }
                                        errorMessage={errors.pay_immediately}
                                    >
                                        <Field
                                            name="pay_immediately"
                                            component={Checkbox}
                                            disabled={actionBtn.approve}
                                            className={
                                                actionBtn.approve
                                                    ? 'changeColor'
                                                    : ''
                                            }
                                        />
                                    </FormItem>
                                </div>
                                <Table compact className="border mb-6">
                                    <THead>
                                        <Tr>
                                            <Th>Items*</Th>
                                            <Th>Qty In Kg*</Th>
                                            <Th>Rate</Th>
                                            <Th>GST Rate</Th>
                                            <Th>Amount</Th>
                                            <Th>GST</Th>
                                            <Th>Total Amount</Th>
                                            <Th
                                                className={
                                                    actionBtn.approve
                                                        ? 'hidden'
                                                        : 'visible'
                                                }
                                            >
                                                Action
                                            </Th>
                                        </Tr>
                                    </THead>
                                    <TBody>
                                        <FieldArray name="paymentVoucherItems">
                                            {({ form, remove, push }) => (
                                                <>
                                                    {paymentVoucherItems &&
                                                    paymentVoucherItems.length >
                                                        0
                                                        ? paymentVoucherItems.map(
                                                              (
                                                                  item_detail,
                                                                  index
                                                              ) => {
                                                                  const particulars =
                                                                      fieldFeedback(
                                                                          form,
                                                                          `paymentVoucherItems[${index}].particulars`
                                                                      )
                                                                  const tax_per =
                                                                      fieldFeedback(
                                                                          form,
                                                                          `paymentVoucherItems[${index}].tax_per`
                                                                      )
                                                                  const qty =
                                                                      fieldFeedback(
                                                                          form,
                                                                          `paymentVoucherItems[${index}].qty`
                                                                      )
                                                                  const rate =
                                                                      fieldFeedback(
                                                                          form,
                                                                          `paymentVoucherItems[${index}].rate`
                                                                      )
                                                                  return (
                                                                      <Tr
                                                                          key={
                                                                              index
                                                                          }
                                                                      >
                                                                          <Td width="350">
                                                                              <FormItem
                                                                                  className="mb-0"
                                                                                  invalid={
                                                                                      particulars.invalid
                                                                                  }
                                                                                  layout="vertical"
                                                                                  errorMessage={
                                                                                      particulars.errorMessage
                                                                                  }
                                                                              >
                                                                                  <Field
                                                                                      invalid={
                                                                                          particulars.invalid
                                                                                      }
                                                                                      placeholder="Item Name"
                                                                                      name={`paymentVoucherItems[${index}].particulars`}
                                                                                      type="text"
                                                                                      component={
                                                                                          Input
                                                                                      }
                                                                                      disabled={
                                                                                          actionBtn.approve
                                                                                      }
                                                                                  />
                                                                              </FormItem>
                                                                          </Td>
                                                                          <Td width="100">
                                                                              <FormItem
                                                                                  className="mb-0"
                                                                                  invalid={
                                                                                      qty.invalid
                                                                                  }
                                                                                  layout="vertical"
                                                                                  errorMessage={
                                                                                      qty.errorMessage
                                                                                  }
                                                                              >
                                                                                  <Field
                                                                                      invalid={
                                                                                          qty.invalid
                                                                                      }
                                                                                      placeholder="Quantity"
                                                                                      name={`paymentVoucherItems[${index}].qty`}
                                                                                      type="number"
                                                                                      onWheel={(
                                                                                          e
                                                                                      ) =>
                                                                                          e.target.blur()
                                                                                      }
                                                                                      component={
                                                                                          Input
                                                                                      }
                                                                                      disabled={
                                                                                          actionBtn.approve
                                                                                      }
                                                                                  />
                                                                              </FormItem>
                                                                          </Td>
                                                                          <Td width="120">
                                                                              <FormItem
                                                                                  className="mb-0"
                                                                                  invalid={
                                                                                      rate.invalid
                                                                                  }
                                                                                  layout="vertical"
                                                                                  errorMessage={
                                                                                      rate.errorMessage
                                                                                  }
                                                                              >
                                                                                  <Field
                                                                                      invalid={
                                                                                          rate.invalid
                                                                                      }
                                                                                      placeholder="Rate"
                                                                                      name={`paymentVoucherItems[${index}].rate`}
                                                                                      type="number"
                                                                                      onWheel={(
                                                                                          e
                                                                                      ) =>
                                                                                          e.target.blur()
                                                                                      }
                                                                                      component={
                                                                                          Input
                                                                                      }
                                                                                      prefix="₹"
                                                                                      disabled={
                                                                                          actionBtn.approve
                                                                                      }
                                                                                  />
                                                                              </FormItem>
                                                                          </Td>
                                                                          <Td width="100">
                                                                              <FormItem
                                                                                  className="mb-0"
                                                                                  invalid={
                                                                                      tax_per.invalid
                                                                                  }
                                                                                  layout="vertical"
                                                                                  errorMessage={
                                                                                      tax_per.errorMessage
                                                                                  }
                                                                              >
                                                                                  <Field
                                                                                      name={`paymentVoucherItems[${index}].tax_per`}
                                                                                  >
                                                                                      {({
                                                                                          form,
                                                                                          field,
                                                                                      }) => (
                                                                                          <Input
                                                                                              invalid={
                                                                                                  tax_per.invalid
                                                                                              }
                                                                                              placeholder="GST %"
                                                                                              type="number"
                                                                                              onWheel={(
                                                                                                  e
                                                                                              ) =>
                                                                                                  e.target.blur()
                                                                                              }
                                                                                              value={
                                                                                                  paymentVoucherItems[
                                                                                                      index
                                                                                                  ]
                                                                                                      .tax_per
                                                                                              }
                                                                                              onChange={(
                                                                                                  e
                                                                                              ) => {
                                                                                                  handleTotal(
                                                                                                      formRef.current
                                                                                                  )
                                                                                                  return form.setFieldValue(
                                                                                                      field.name,
                                                                                                      e
                                                                                                          .target
                                                                                                          .value
                                                                                                  )
                                                                                              }}
                                                                                              suffix="%"
                                                                                              disabled={
                                                                                                  actionBtn.approve
                                                                                              }
                                                                                          />
                                                                                      )}
                                                                                  </Field>
                                                                              </FormItem>
                                                                          </Td>
                                                                          <Td width="150">
                                                                              <p>
                                                                                  <NumberFormat
                                                                                      displayType="text"
                                                                                      prefix={
                                                                                          '₹'
                                                                                      }
                                                                                      thousandsGroupStyle={
                                                                                          'lakh'
                                                                                      }
                                                                                      decimalScale={
                                                                                          2
                                                                                      }
                                                                                      value={
                                                                                          (paymentVoucherItems[
                                                                                              index
                                                                                          ].amount =
                                                                                              parseFloat(
                                                                                                  paymentVoucherItems[
                                                                                                      index
                                                                                                  ]
                                                                                                      .qty
                                                                                              ) *
                                                                                              parseFloat(
                                                                                                  paymentVoucherItems[
                                                                                                      index
                                                                                                  ]
                                                                                                      .rate
                                                                                              ))
                                                                                      }
                                                                                      allowLeadingZeros
                                                                                      thousandSeparator=","
                                                                                  />
                                                                              </p>
                                                                          </Td>
                                                                          <Td width="150">
                                                                              <p>
                                                                                  <NumberFormat
                                                                                      displayType="text"
                                                                                      prefix={
                                                                                          '₹'
                                                                                      }
                                                                                      thousandsGroupStyle={
                                                                                          'lakh'
                                                                                      }
                                                                                      decimalScale={
                                                                                          2
                                                                                      }
                                                                                      value={
                                                                                          (paymentVoucherItems[
                                                                                              index
                                                                                          ].tax_amt =
                                                                                              (parseFloat(
                                                                                                  paymentVoucherItems[
                                                                                                      index
                                                                                                  ]
                                                                                                      .amount
                                                                                              ) *
                                                                                                  parseFloat(
                                                                                                      paymentVoucherItems[
                                                                                                          index
                                                                                                      ]
                                                                                                          .tax_per
                                                                                                  )) /
                                                                                              100)
                                                                                      }
                                                                                      allowLeadingZeros
                                                                                      thousandSeparator=","
                                                                                  />
                                                                              </p>
                                                                          </Td>
                                                                          <Td width="150">
                                                                              <p>
                                                                                  <NumberFormat
                                                                                      displayType="text"
                                                                                      prefix={
                                                                                          '₹'
                                                                                      }
                                                                                      thousandsGroupStyle={
                                                                                          'lakh'
                                                                                      }
                                                                                      decimalScale={
                                                                                          2
                                                                                      }
                                                                                      value={
                                                                                          (paymentVoucherItems[
                                                                                              index
                                                                                          ].total_amt =
                                                                                              paymentVoucherItems[
                                                                                                  index
                                                                                              ]
                                                                                                  .amount +
                                                                                              paymentVoucherItems[
                                                                                                  index
                                                                                              ]
                                                                                                  .tax_amt)
                                                                                      }
                                                                                      allowLeadingZeros
                                                                                      thousandSeparator=","
                                                                                  />
                                                                              </p>
                                                                          </Td>
                                                                          <Td
                                                                              width="80"
                                                                              className={
                                                                                  actionBtn.approve
                                                                                      ? 'hidden'
                                                                                      : 'visible'
                                                                              }
                                                                          >
                                                                              <Button
                                                                                  shape="circle"
                                                                                  size="sm"
                                                                                  icon={
                                                                                      <HiMinus />
                                                                                  }
                                                                                  onClick={() =>
                                                                                      remove(
                                                                                          index
                                                                                      )
                                                                                  }
                                                                                  disabled={
                                                                                      index ==
                                                                                      0
                                                                                          ? true
                                                                                          : false
                                                                                  }
                                                                              />
                                                                          </Td>
                                                                      </Tr>
                                                                  )
                                                              }
                                                          )
                                                        : null}
                                                    <Tr
                                                        className={
                                                            actionBtn.approve
                                                                ? 'hidden'
                                                                : 'visible'
                                                        }
                                                    >
                                                        <Td
                                                            colSpan="8"
                                                            className="custom-text-left"
                                                        >
                                                            <Button
                                                                type="button"
                                                                className="ltr:mr-2 rtl:ml-2"
                                                                onClick={() => {
                                                                    push({
                                                                        particulars:
                                                                            '',
                                                                        qty: '',
                                                                        rate: '',
                                                                        tax_per:
                                                                            '',
                                                                        amount: '',
                                                                        tax_amt:
                                                                            '',
                                                                        total_amt:
                                                                            '',
                                                                    })
                                                                }}
                                                            >
                                                                Add Item
                                                            </Button>
                                                        </Td>
                                                    </Tr>
                                                    <Tr>
                                                        <Td colSpan="4"></Td>
                                                        <Td colSpan="2">
                                                            Total Amount
                                                        </Td>
                                                        <Td>
                                                            <NumberFormat
                                                                displayType="text"
                                                                prefix={'₹'}
                                                                thousandsGroupStyle={
                                                                    'lakh'
                                                                }
                                                                decimalScale={2}
                                                                value={
                                                                    values.total_payable
                                                                }
                                                                allowLeadingZeros
                                                                thousandSeparator=","
                                                            />
                                                        </Td>
                                                        <Td
                                                            className={
                                                                actionBtn.approve
                                                                    ? 'hidden'
                                                                    : 'visible'
                                                            }
                                                        ></Td>
                                                    </Tr>
                                                    <Tr>
                                                        <Td colSpan="4"></Td>
                                                        <Td colSpan="1">
                                                            TDS(%)
                                                        </Td>
                                                        <Td>
                                                            <FormItem
                                                                className="mb-0"
                                                                invalid={
                                                                    errors.tds_per &&
                                                                    touched.tds_per
                                                                }
                                                                layout="vertical"
                                                                errorMessage={
                                                                    errors.tds_per
                                                                }
                                                            >
                                                                <Field name="tds_per">
                                                                    {({
                                                                        form,
                                                                        field,
                                                                    }) => (
                                                                        <Input
                                                                            type="number"
                                                                            placeholder="TDS %"
                                                                            layout="vertical"
                                                                            className="mb-0"
                                                                            size="sm"
                                                                            suffix="%"
                                                                            value={
                                                                                values.tds_per
                                                                            }
                                                                            onWheel={(
                                                                                e
                                                                            ) =>
                                                                                e.target.blur()
                                                                            }
                                                                            onChange={(
                                                                                e
                                                                            ) => {
                                                                                calcTDS(
                                                                                    e
                                                                                )
                                                                            }}
                                                                            disabled={
                                                                                actionBtn.approve
                                                                            }
                                                                        />
                                                                    )}
                                                                </Field>
                                                            </FormItem>
                                                        </Td>
                                                        <Td>
                                                            <NumberFormat
                                                                displayType="text"
                                                                prefix={'₹'}
                                                                thousandsGroupStyle={
                                                                    'lakh'
                                                                }
                                                                decimalScale={2}
                                                                value={
                                                                    values.tdsamount
                                                                }
                                                                allowLeadingZeros
                                                                thousandSeparator=","
                                                            />
                                                        </Td>
                                                        <Td
                                                            className={
                                                                actionBtn.approve
                                                                    ? 'hidden'
                                                                    : 'visible'
                                                            }
                                                        ></Td>
                                                    </Tr>
                                                    <Tr>
                                                        <Td colSpan="4"></Td>
                                                        <Td colSpan="2">
                                                            Round Off Amount
                                                        </Td>
                                                        <Td>
                                                            <FormItem
                                                                className="mb-0"
                                                                invalid={
                                                                    errors.round_off_amount &&
                                                                    touched.round_off_amount
                                                                }
                                                                layout="vertical"
                                                                errorMessage={
                                                                    errors.round_off_amount
                                                                }
                                                            >
                                                                <Field name="round_off_amount">
                                                                    {({
                                                                        form,
                                                                        field,
                                                                    }) => (
                                                                        <Input
                                                                            type="number"
                                                                            placeholder="TDS %"
                                                                            layout="vertical"
                                                                            className="mb-0"
                                                                            size="sm"
                                                                            suffix="%"
                                                                            value={
                                                                                values.round_off_amount
                                                                            }
                                                                            onWheel={(
                                                                                e
                                                                            ) =>
                                                                                e.target.blur()
                                                                            }
                                                                            onChange={(
                                                                                e
                                                                            ) => {
                                                                                calcRound(
                                                                                    e
                                                                                )
                                                                            }}
                                                                            disabled={
                                                                                actionBtn.approve
                                                                            }
                                                                        />
                                                                    )}
                                                                </Field>
                                                            </FormItem>
                                                        </Td>
                                                        <Td
                                                            className={
                                                                actionBtn.approve
                                                                    ? 'hidden'
                                                                    : 'visible'
                                                            }
                                                        ></Td>
                                                    </Tr>
                                                    <Tr>
                                                        <Td colSpan="4"></Td>
                                                        <Td colSpan="2">
                                                            Final Amount
                                                        </Td>
                                                        <Td>
                                                            <NumberFormat
                                                                displayType="text"
                                                                prefix={'₹'}
                                                                thousandsGroupStyle={
                                                                    'lakh'
                                                                }
                                                                decimalScale={2}
                                                                value={
                                                                    values.final_amount
                                                                }
                                                                allowLeadingZeros
                                                                thousandSeparator=","
                                                            />
                                                        </Td>
                                                        <Td
                                                            className={
                                                                actionBtn.approve
                                                                    ? 'hidden'
                                                                    : 'visible'
                                                            }
                                                        ></Td>
                                                    </Tr>
                                                </>
                                            )}
                                        </FieldArray>
                                    </TBody>
                                </Table>
                                <div className="grid grid-cols-3 gap-x-8 gap-y-2">
                                    <FormItem
                                        label="Remark"
                                        invalid={
                                            errors.remarks && touched.remarks
                                        }
                                        errorMessage={errors.remarks}
                                    >
                                        <Field name="remarks">
                                            {({ field, form }) => {
                                                return (
                                                    <Input
                                                        type="text"
                                                        field={field}
                                                        form={form}
                                                        // name={field.name}
                                                        value={field.value}
                                                        onChange={(option) =>
                                                            form.setFieldValue(
                                                                field.name,
                                                                option.target
                                                                    .value
                                                            )
                                                        }
                                                    />
                                                )
                                            }}
                                        </Field>
                                    </FormItem>
                                </div>
                            </FormContainer>
                        </AdaptableCard>
                        <StickyFooter
                            className="-mx-1 md:-mx-1 px-8 flex items-center justify-between py-4"
                            stickyClass="border bg-white dark:bg-gray-800 border-gray-200 dark:border-gray-700"
                        >
                            <div>
                                {/* <Button
                                    size="sm"
                                    type="submit"
                                    variant="solid"
                                    color="emerald-600"
                                    className={
                                        'ltr:mr-6 rtl:ml-6 ' +
                                        (actionBtn.approve ? '' : 'hidden')
                                    }
                                    disabled={isSubmitting}
                                >
                                    Approve
                                </Button>
                                <Button
                                    size="sm"
                                    type="button"
                                    variant="solid"
                                    color="red-600"
                                    onClick={() => rejectFinanceVoucher()}
                                    disabled={isSubmitting}
                                    className={
                                        'ltr:mr-3 rtl:ml-3 ' +
                                        (actionBtn.approve ? '' : 'hidden')
                                    }
                                >
                                    Reject
                                </Button> */}
                            </div>
                            <div className="md:flex items-center">
                                <Button
                                    size="sm"
                                    type="submit"
                                    className={
                                        'ltr:mr-3 rtl:ml-3 ' +
                                        (actionBtn.approve ? 'hidden' : '')
                                    }
                                    variant="solid"
                                    disabled={isSubmitting}
                                >
                                    {actionBtn.update
                                        ? 'Sumit For Approval'
                                        : 'Save'}
                                </Button>
                                <Button
                                    size="sm"
                                    type="button"
                                    variant="solid"
                                    color="red-600"
                                    onClick={() => deleteFinanceVoucher()}
                                    disabled={isSubmitting}
                                    className={
                                        'ltr:mr-3 rtl:ml-3 ' +
                                        (actionBtn.delete ? '' : 'hidden')
                                    }
                                >
                                    Delete
                                </Button>
                                <Button
                                    size="sm"
                                    type="button"
                                    onClick={() =>
                                        navigate('/transaction/finance-voucher')
                                    }
                                >
                                    Discard
                                </Button>
                            </div>
                        </StickyFooter>
                    </Form>
                )
            }}
        </Formik>
    )
}

export default AddFinanceVoucher
